mapper.select:
select

,f.id as f_id,f.name as f_name,f.file_url as f_file_url,f.save_type as f_save_type, f.video_long as f_video_long
from
gc_user_event_resource r
left join sys_file f on r.file_id=f.id
where r.user_id = #{userId}
and r.type != ${@com.threeatom.guidecore.constant.EventResType@TEXT_0} 
and r.event_id in

    #{eventId}

SELECT e.event_title,vr.user_id,vr.update_time,vr.event_id FROM gc_user_event_resource AS vr LEFT JOIN gc_event AS e ON e.id = vr.event_id LEFT JOIN gc_video AS v ON v.id = e.video_id LEFT JOIN gc_subject AS s ON s.id = v.sub_id WHERE s.master_id = #{masterId} AND (vr.target_user_id = 0 or vr.target_user_id is null) AND ((vr.type = ${@com.threeatom.guidecore.constant.EventResType@VIDEO_2} and vr.time_node=-1) or vr.time_node!=-1)
AND vr.user_id IN
#{uId}
OR vr.user_id = #{userId}
AND vr.target_user_id IN
#{uId}
ORDER BY vr.update_time DESC

SELECT
,f.id as f_id,f.name as f_name,f.file_url as f_file_url,f.save_type as f_save_type, f.video_long as f_video_long ,f2.id as a_f_id,f2.name as a_f_name,f2.file_url as a_f_file_url,f2.save_type as a_f_save_type FROM gc_user_event_resource r LEFT JOIN sys_file f ON r.file_id=f.id LEFT JOIN gc_user u ON r.user_id=u.id LEFT JOIN gc_user_info ui on ui.id=u.info_id LEFT JOIN sys_file f2 ON ui.avatar_file_id=f2.id WHERE r.target_id=#{targetId} and r.time_node!=-1
and r.user_id=#{userId}

mapper.sql:
FROM gc_user_event_resource AS vr
LEFT JOIN gc_event AS e ON e.id = vr.event_id
LEFT JOIN gc_user AS u ON u.id = vr.user_id
LEFT JOIN sys_file AS f2 ON f2.id = vr.file_id
LEFT JOIN gc_master_message AS m ON m.res_id = vr.id


    left join gc_user_access ua2 on ua2.user_id = u.id and m.master_id = ua.master_id
    left join gc_group g ON g.group_access_ids::jsonb @> to_jsonb(ua2.id::integer) and g.master_id = m.master_id

WHERE
m.master_id=#{masterId}
and m.target_user_id = #{thisUserId}
and ua.user_id=#{thisUserId}
and vr.user_id!=#{thisUserId}
and ua.master_id=#{masterId}


    and m.read_state = #{readState}


    and vr.update_time  > now() - '#{lastDaysScope} days'::interval


    and vr.user_id = #{sendUserId}


    and g.id=#{groupId}

mapper.select:
SELECT
,vr.id, vr.user_id, vr.content, vr.type, vr.time_node, vr.update_time, vr.target_user_id, vr.target_id, vr.event_id, f2.save_type AS res_save_type, f2.name AS res_file_name, f2.file_url as res_file_url, f2.file_type_index as res_file_type_index, f2.thumb_nail_url as thumb_nail_url, s0.name as sub0Name, s.name as sub1Name FROM gc_user_event_resource AS vr LEFT JOIN gc_event AS e ON e.id = vr.event_id LEFT JOIN gc_user AS u ON u.id = vr.user_id LEFT JOIN sys_file AS f2 ON f2.id = vr.file_id LEFT JOIN gc_master_message AS m ON m.res_id = vr.id
left join gc_user_access ua2 on ua2.user_id = u.id and m.master_id = ua.master_id left join gc_group g ON g.group_access_ids::jsonb @> to_jsonb(ua2.id::integer) and g.master_id = m.master_id
WHERE m.master_id=#{message.masterId} and m.target_user_id = #{message.thisUserId} and ua.user_id=#{message.thisUserId} and vr.user_id!=#{message.thisUserId} and ua.master_id=#{message.masterId}
and m.read_state = #{message.readState}
and vr.update_time > now() - '#{message.lastDaysScope} days'::interval
and vr.user_id = #{message.sendUserId}
and g.id=#{message.groupId}
and s.sub_id in
#{item}
and gv.id in
#{videoId}
and s0.sub_id in
#{item}
ORDER BY vr.update_time ${pageParam.orderByString}
ORDER BY vr.update_time desc

mapper.sql:
FROM   gc_user_answer AS answer
LEFT JOIN gc_master_message AS m ON m.user_answer_id = answer.id
LEFT JOIN gc_event AS e ON e.id = answer.event_id
LEFT JOIN gc_user AS u ON u.id = answer.user_id



    left join gc_user_access ua2 on ua2.user_id = u.id and m.master_id = ua.master_id
    left join gc_group g ON g.group_access_ids::jsonb @> to_jsonb(ua2.id::integer) and g.master_id = m.master_id


WHERE
m.master_id=#{masterId} and m.target_user_id = #{thisUserId}
and ua.user_id=#{thisUserId} and ua.master_id=#{masterId}


    and m.read_state = #{readState}


    and answer.update_time  > now() - '#{lastDaysScope} days'::interval


    and answer.user_id = #{sendUserId}


    and g.id=#{groupId}

mapper.select:
SELECT
,answer.id as answer_id, answer.user_id, m.update_time, answer.event_id, answer.answer_json, s.name as topicName, s0.name as subjectName, sys.file_url as subjectAvatarFileUrl, sys.save_type as subjectAvatarSaveType FROM gc_user_answer AS answer LEFT JOIN gc_master_message AS m ON m.user_answer_id = answer.id LEFT JOIN gc_event AS e ON e.id = answer.event_id LEFT JOIN gc_user AS u ON u.id = answer.user_id
left join gc_user_access ua2 on ua2.user_id = u.id and m.master_id = ua.master_id left join gc_group g ON g.group_access_ids::jsonb @> to_jsonb(ua2.id::integer) and g.master_id = m.master_id
WHERE m.master_id=#{message.masterId} and m.target_user_id = #{message.thisUserId} and ua.user_id=#{message.thisUserId} and ua.master_id=#{message.masterId}
and m.read_state = #{message.readState}
and answer.update_time > now() - '#{message.lastDaysScope} days'::interval
and answer.user_id = #{message.sendUserId}
and g.id=#{message.groupId}
and e.id=#{message.eventId}
and s.sub_id in
#{item}
ORDER BY answer.update_time ${pageParam.orderByString}
ORDER BY answer.update_time desc
